"""Pure prompt branch tests; legacy golden generated by original public source."""
import sys,unittest
if sys.version_info<(3,10):raise unittest.SkipTest('Project prompt tests require Python3.10+ before engine import')
import hashlib
from evolution.tool_campaign import build_prompt
from evolution.isolated_python import EXECUTION_BACKEND
from evolution.engineering_broker import BACKEND_ID

class ProjectPromptTests(unittest.TestCase):
    def test_prompt_original_default_and_finite_wire_golden(self):
        rows=[({},'688ac016b1754ede7de4940a4f8bc6dc47557bb74d4be5b544748c5ead74ef8e'),
            ({'terminal_report':'native-tool'},'b9f840f9e5c5b8d61675c7e0eabece87a02995dc2a689b4a807f15530c121289'),
            ({'execution_backend':EXECUTION_BACKEND},'2be9fb25036f7d48d0ec2c6093bbd92e03d7a6825e4c026b9b156d09efdb19f1'),
            ({'terminal_report':'native-tool','execution_backend':EXECUTION_BACKEND},'ec021451d7248c874deb64396ef47b8064d8259a3c9c6597463178855cc1d64d')]
        for options,expected in rows:
            with self.subTest(options=options):self.assertEqual(hashlib.sha256(build_prompt('public Skill',{'public':True},'public task',**options).encode()).hexdigest(),expected)

    def test_prompt_project_uses_registered_scope_and_exact_delimiters(self):
        plan='{"public": true}'
        value=build_prompt('public Skill',plan,'public task',terminal_report='native-tool',execution_backend=BACKEND_ID)
        self.assertIn('registered stdlib Python project suite in isolated CPython',value)
        self.assertIn('package imports, unittest, CLI and registered file processing',value)
        self.assertNotIn('finite VM',value);self.assertNotIn('broker cannot execute',value)
        self.assertIn('<governance_plan>\n'+plan+'\n</governance_plan>',value)
        self.assertIn('Finish by calling repo_finish alone',value)
        self.assertIn('persistent governance state are unavailable',value)

    def test_prompt_unregistered_backend_is_rejected(self):
        for value in ('project-arbitrary-v1',True,{},42):
            with self.subTest(value=value),self.assertRaises(ValueError):build_prompt('',{},'',execution_backend=value)
